def cache_sim(capacity, ttl, ops):
    cache = {}
    lru_order = []
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Check if key exists and is not expired
            if key in cache:
                write_time, _ = cache[key]
                if t < write_time + ttl:
                    # Key exists and not expired, remove from lru_order
                    lru_order.remove(key)
                else:
                    # Key exists but expired, treat as absent
                    pass
            else:
                # Key doesn't exist, check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]

            # Add the new entry
            cache[key] = (t, value)
            lru_order.append(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache:
                write_time, value = cache[key]
                if t < write_time + ttl:
                    # Key exists and not expired
                    results.append(value)
                    # Make it most recently used
                    lru_order.remove(key)
                    lru_order.append(key)
                else:
                    # Key exists but expired
                    results.append(-1)
            else:
                # Key doesn't exist
                results.append(-1)

    return results

